// готовая функция: первые failTimes вызовов падают, потом успех
function makeFlaky(failTimes) {
  let calls = 0;
  return () => new Promise((resolve, reject) => {
    setTimeout(() => {
      calls += 1;
      if (calls <= failTimes) reject(new Error("503"));
      else resolve("ok");
    }, 10);
  });
}

async function retryRequest(failTimes, attempts) {
  const task = makeFlaky(failTimes);
  for (let i = 1; i <= attempts; i += 1) {
    try {
      await task();
      return { ok: true, tries: i };
    } catch {
      // попробуем ещё раз
    }
  }
  return { ok: false, tries: attempts };
}

