// src/main.js
import { getCourses, createCourse, updateCourse, deleteCourse } from "./api/courses.js";
import { getErrorMessage } from "./api/errors.js";

const list = document.querySelector("#list");
const status = document.querySelector("#status");
const form = document.querySelector("#form");
let courses = [];

function render() {
  list.textContent = "";
  status.textContent = courses.length === 0 ? "Курсов пока нет" : "";
  for (const course of courses) {
    const li = document.createElement("li");
    const title = document.createElement("span");
    title.textContent = course.done ? `✓ ${course.title}` : course.title;
    const toggle = document.createElement("button");
    toggle.textContent = course.done ? "Не готово" : "Готово";
    toggle.addEventListener("click", () => toggleDone(course.id));
    const remove = document.createElement("button");
    remove.textContent = "Удалить";
    remove.addEventListener("click", () => removeCourse(course.id));
    li.append(title, toggle, remove);
    list.append(li);
  }
}

async function load() {
  status.textContent = "Загрузка…";
  try {
    courses = await getCourses();
    render();
  } catch (error) {
    status.textContent = getErrorMessage(error);
  }
}

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  const title = form.title.value.trim();
  if (title === "") return;
  form.submit.disabled = true;
  try {
    const created = await createCourse({ title, done: false });
    courses = [...courses, created];
    form.reset();
    render();
  } catch (error) {
    status.textContent = getErrorMessage(error);
  } finally {
    form.submit.disabled = false;
  }
});

async function toggleDone(id) {
  const previous = courses;
  const target = courses.find(course => course.id === id);
  courses = courses.map(course => (course.id === id ? { ...course, done: !course.done } : course));
  render();
  try {
    await updateCourse(id, { done: !target.done });
  } catch (error) {
    courses = previous;
    render();
    status.textContent = getErrorMessage(error);
  }
}

async function removeCourse(id) {
  if (!confirm("Удалить курс?")) return;
  try {
    await deleteCourse(id);
    courses = courses.filter(course => course.id !== id);
    render();
  } catch (error) {
    status.textContent = getErrorMessage(error);
  }
}

load();

function auditProject(project) {
  const problems = [];
  if (!project.envInGitignore) problems.push(".env не в .gitignore");
  if (!project.hasEnvExample) problems.push("нет .env.example");
  if (!project.hasReadme) problems.push("нет README");
  if (!(typeof project.timeoutMs === "number" && project.timeoutMs > 0)) problems.push("нет timeout");
  if (!project.disablesButtons) problems.push("кнопки не отключаются");
  if (Array.isArray(project.secretsInCode) && project.secretsInCode.length > 0) problems.push("секреты в коде");
  return problems;
}

